To determine how many people are wearing red shirts, we first need to load the image and detect the people and shirts using the Image_Detector.Tool tool. Then, we can count the number of people wearing red shirts.

<command>
from object_detector_tool import *

input_image_path = "/home/stud/wxie/BLINK_Dataset/Counting/val/images/val_Counting_8_image_1.jpg"  # Insert the path to your image file
labels = ["person"]  # Replace with the actual labels to be detected

output = []
for image, labels in execution:
    if "person" in labels:
        for person_info in image:
            if "label" in person_info and person_info["label"] == "person":
                output.append({"label": 'person', "confidence score": person_info["confidence"], "box": person_info["bbox"], "saved_image_path": None})

output_counts = {label: count for label, count in counter(output).items() if label == "person"}

people_with_red_shirt = output_counts["person"]
people_with_red_shirt, people_without_red_shirt = round(people_with_red_shirt), len((people_with_red_shirt - people_with_red_shirt)) if people_with_red_shirt > 0 else 0
</command>
